def split(grid):
    h,w=len(grid),len(grid[0])
    for i,row in enumerate(grid):
        if len(set(row))==1 and row[0]!=0: return 'row',i
    for j in range(w):
        if len({r[j] for r in grid})==1 and grid[0][j]!=0: return 'col',j

def transform(grid):
    kind,i=split(grid)
    if kind=='row':
        A,B=grid[:i],grid[i+1:]
    else:
        A,B=[r[:i] for r in grid],[r[i+1:] for r in grid]
    return [[2 if a!=0 and b!=0 else 0 for a,b in zip(ra,rb)] for ra,rb in zip(A,B)]

